-- Add word and phrase hint packs for the 400 intro foundation prompts.
-- Generated from prompt-intro-v2-* question text on 2026-05-12.

SET NAMES utf8mb4;

START TRANSACTION;

UPDATE prompt_hint_items item
JOIN prompt_hints hint ON hint.id = item.hint_id
SET item.is_active = 0
WHERE hint.prompt_id LIKE 'prompt-intro-v2-%'
  AND hint.hint_type IN ('VOCAB_WORD', 'VOCAB_PHRASE');

UPDATE prompt_hints
SET is_active = 0
WHERE prompt_id LIKE 'prompt-intro-v2-%'
  AND hint_type IN ('VOCAB_WORD', 'VOCAB_PHRASE');

ON DUPLICATE KEY UPDATE
    prompt_id = VALUES(prompt_id),
    hint_type = VALUES(hint_type),
    title = VALUES(title),
    display_order = VALUES(display_order),
    is_active = VALUES(is_active);

ON DUPLICATE KEY UPDATE
    hint_id = VALUES(hint_id),
    item_type = VALUES(item_type),
    content = VALUES(content),
    meaning_ko = VALUES(meaning_ko),
    usage_tip_ko = VALUES(usage_tip_ko),
    example_en = VALUES(example_en),
    expression_family = VALUES(expression_family),
    display_order = VALUES(display_order),
    is_active = VALUES(is_active);

COMMIT;
